/* BESTIAIRE — données : mammifères (suite) et oiseaux (suite) */
window.ANIMAUX = (window.ANIMAUX || []).concat([

/* ============ MAMMIFÈRES ============ */

{id:"rhinoceros-blanc",nom:"Rhinocéros blanc",sci:"Ceratotherium simum",emo:"🦏",gr:"Mammifère",ord:"Perissodactyla",fam:"Rhinocérotidés",bio:"savane",
hab:"Savanes herbeuses",rep:"Afrique australe et de l'Est",taille:"3,5 à 4 m",poidsKg:2300,vit:50,vie:45,
reg:"Herbivore",uicn:"NT",rar:4,
res:"Le deuxième plus gros animal terrestre. Sa corne, qui n'a aucune propriété médicale, vaut plus cher que l'or au marché noir.",
f:[["Sa corne n'est pas un os : c'est de la kératine compactée, la même matière que tes ongles. Elle n'est même pas fixée au crâne, juste posée sur la peau. Elle repousse si on la coupe.","base"],
["« Blanc » est une erreur de traduction : l'afrikaans wyd signifie « large », en référence à sa lèvre carrée de brouteur d'herbe rase. Le rhinocéros noir, lui, a une lèvre préhensile pour attraper les branches. Ils sont de la même couleur.","pointu"],
["La sous-espèce du Nord est fonctionnellement éteinte : il ne reste que deux femelles, Najin et sa fille Fatu, incapables de porter une gestation. Des embryons créés en laboratoire à partir de sperme congelé attendent une mère porteuse rhinocéros du Sud. L'espèce survit aujourd'hui dans un congélateur.","expert"],
["Il dépose ses excréments dans des latrines communes. Chaque bouse porte une signature chimique qui indique l'âge, le sexe et l'état reproducteur de son auteur — un tableau d'affichage collectif.","expert"]],
v:[["Sous-espèce","Population isolée d'une même espèce, aux caractères propres. Quand la dernière sous-espèce d'une lignée disparaît, l'espèce reste — mais une branche entière de sa diversité est perdue définitivement."]],
q:[["De quoi est faite la corne du rhinocéros ?",["D'os","De kératine","D'ivoire","De corne creuse"],1,"Comme tes ongles — et elle n'est même pas soudée au crâne."],
["Pourquoi l'appelle-t-on « blanc » ?",["Sa peau est claire","Erreur de traduction : « large » en afrikaans, pour sa lèvre carrée","Il se roule dans la craie","Ses cornes sont pâles"],1,"Le rhinocéros noir est exactement de la même couleur."]],
d:["retour","records"]},

{id:"leopard-neiges",nom:"Léopard des neiges",sci:"Panthera uncia",emo:"🐆",gr:"Mammifère",ord:"Carnivora",fam:"Félidés",bio:"montagne",
hab:"Montagnes rocheuses, 3 000 à 5 500 m",rep:"Asie centrale, Himalaya",taille:"1,1 à 1,3 m",poidsKg:45,vit:65,vie:18,
reg:"Carnivore",uicn:"VU",rar:5,
res:"Le « fantôme des montagnes ». Un Panthera qui ne rugit pas, capable de tuer une proie trois fois son poids sur une pente de glace.",
f:[["Sa queue fait presque la longueur de son corps. Elle sert de balancier dans les pentes, et il s'en couvre le museau pour dormir — une écharpe.","base"],
["C'est un Panthera, comme le lion et le tigre, mais il ne rugit pas. L'os hyoïde de sa gorge est partiellement ossifié : il ronronne, feule et pousse un cri appelé « chuff », jamais un rugissement.","pointu"],
["Ses narines sont exceptionnellement larges et sa cavité nasale profonde : l'air glacial et raréfié de l'altitude est réchauffé et humidifié avant d'atteindre les poumons.","pointu"],
["Il est presque impossible à compter. Les estimations, entre 4 000 et 7 000 individus, reposent sur des pièges photographiques et des analyses génétiques de crottes. Une bonne part de ce qu'on croit savoir de sa population est une extrapolation, et les chercheurs le disent eux-mêmes.","expert"],
["Aucune attaque mortelle sur un humain n'est documentée, ce qui est unique chez les grands félins.","base"]],
v:[["Os hyoïde","Petit os en U de la gorge qui soutient le larynx. Chez le lion et le tigre, il reste souple, ce qui permet le rugissement. Chez le léopard des neiges et les petits félins, il s'ossifie — mais le ronronnement devient possible."]],
q:[["Pourquoi le léopard des neiges ne rugit-il pas ?",["Il est trop petit","Son os hyoïde est partiellement ossifié","Il vit trop haut","Il est muet"],1,"Il ronronne et « chuffe » à la place."],
["Que sait-on précisément de sa population ?",["Elle est comptée chaque année","Elle est estimée entre 4 000 et 7 000, avec une forte incertitude","Elle dépasse 50 000","Elle est stable à 100 individus près"],1,"Les chercheurs eux-mêmes soulignent la marge d'erreur."]],
d:["extremes","camouflage"]},

{id:"suricate",nom:"Suricate",sci:"Suricata suricatta",emo:"🦫",gr:"Mammifère",ord:"Carnivora",fam:"Herpestidés",bio:"desert",
hab:"Déserts et savanes arides",rep:"Sud de l'Afrique",taille:"25 à 35 cm",poidsKg:0.73,vit:32,vie:12,
reg:"Insectivore",uicn:"LC",rar:2,
res:"L'un des rares animaux chez qui on a démontré un véritable enseignement : les adultes graduent la difficulté pour former les jeunes.",
f:[["Une sentinelle monte la garde pendant que les autres creusent, et pousse des cris différents selon le danger : aérien ou terrestre. Le groupe réagit différemment à chacun.","base"],
["Les adultes apportent aux petits des scorpions d'abord morts, puis vivants mais amputés de leur dard, puis vivants et intacts — en fonction de l'âge du jeune. Ils changent de comportement au seul son des cris du petit. C'est l'un des rares cas d'enseignement authentique documenté hors de notre espèce, publié en 2006.","expert"],
["Ils résistent au venin de scorpion, mais pas totalement : une piqûre les rend malades. Le dressage progressif sert précisément à limiter les accidents pendant l'apprentissage.","pointu"],
["La femelle dominante monopolise la reproduction et chasse parfois les subordonnées qui tombent enceintes. Celles-ci reviennent ensuite servir de nourrices — le même dilemme que chez les insectes eusociaux, à petite échelle.","expert"]],
v:[["Enseignement","Au sens strict : modifier son comportement, à un coût pour soi, uniquement en présence d'un naïf, de façon à accélérer son apprentissage. Trois critères stricts, remplis par très peu d'espèces."]],
q:[["Comment les suricates forment-ils leurs petits à chasser le scorpion ?",["En les laissant faire","En graduant la difficulté : mort, puis désarmé, puis intact","En chassant devant eux","Ils ne les forment pas"],1,"Un des rares cas d'enseignement authentique documenté chez un animal."],
["Que suppose l'enseignement au sens strict ?",["Répéter un geste","Modifier son comportement à ses frais, face à un naïf, pour accélérer son apprentissage","Imiter un adulte","Punir les erreurs"],1,"Trois critères exigeants — très peu d'espèces les remplissent."]],
d:["eusocial","venins"]},

{id:"taupe-nez-etoile",nom:"Condylure à nez étoilé",sci:"Condylura cristata",emo:"⭐",gr:"Mammifère",ord:"Eulipotyphla",fam:"Talpidés",bio:"souterrain",
hab:"Sols humides, marais",rep:"Nord-est de l'Amérique du Nord",taille:"15 à 20 cm",poidsKg:0.055,vit:null,vie:4,
reg:"Insectivore",uicn:"LC",rar:4,
res:"Le chasseur le plus rapide du règne animal. Son nez à vingt-deux tentacules est l'organe tactile le plus sensible jamais mesuré.",
f:[["Son museau porte 22 appendices charnus disposés en étoile, couverts de plus de 25 000 organes d'Eimer — des récepteurs tactiles microscopiques. Sur un centimètre carré de peau, il y a six fois plus de fibres nerveuses que dans une main humaine entière.","pointu"],
["Il identifie une proie et décide de l'avaler en 8 millisecondes. Le temps de réaction est si court qu'il approche la limite physique de transmission de son propre système nerveux. C'est le repas le plus rapide jamais chronométré chez un mammifère.","expert"],
["L'étoile n'est pas un organe olfactif : c'est un organe tactile. Le cerveau lui consacre une carte détaillée, exactement comme le nôtre consacre une surface disproportionnée aux mains et aux lèvres.","pointu"],
["Il sent sous l'eau : il expire une bulle d'air sur un objet, la bulle capte les molécules odorantes, il la réinspire. Filmé à grande vitesse en 2006, ce comportement était jugé impossible chez un mammifère.","expert"]],
v:[["Organe d'Eimer","Récepteur tactile de la peau des taupes, formé d'une colonne de cellules reliées à plusieurs fibres nerveuses. Il détecte les micro-déformations de la surface."]],
q:[["En combien de temps le condylure décide-t-il d'avaler une proie ?",["1 seconde","8 millisecondes","2 minutes","1 dixième de seconde"],1,"Proche de la limite physique de son propre système nerveux."],
["Comment sent-il sous l'eau ?",["Par ses tentacules","En expirant une bulle puis en la réinspirant","Il ne sent pas sous l'eau","Par sa langue"],1,"Un comportement filmé en 2006, jugé impossible auparavant."]],
d:["sens","records"]},

{id:"castor",nom:"Castor européen",sci:"Castor fiber",emo:"🦫",gr:"Mammifère",ord:"Rodentia",fam:"Castoridés",bio:"riviere",
hab:"Rivières et étangs boisés",rep:"Europe, Asie occidentale",taille:"80 à 100 cm",poidsKg:20,vit:null,vie:17,
reg:"Herbivore",uicn:"LC",rar:3,
res:"Le seul animal après nous qui transforme délibérément un paysage entier. On le réintroduit aujourd'hui comme on installerait une infrastructure.",
f:[["Ses incisives sont orange parce que leur émail est renforcé au fer. Cet alliage naturel est plus dur que celui de nos dents, et il s'use moins vite sur la face avant que sur l'arrière — la dent s'auto-aiguise en biseau.","pointu"],
["Il construit ses barrages en réaction au bruit de l'eau qui coule. On l'a démontré en diffusant un enregistrement de ruissellement près d'une berge sèche : les castors ont recouvert le haut-parleur de boue et de branches.","expert"],
["Ses étangs ralentissent les crues, filtrent les nitrates, rechargent les nappes et créent des zones humides pour des centaines d'espèces. Plusieurs pays européens le réintroduisent désormais comme un outil de gestion de l'eau — moins cher qu'un ouvrage de génie civil.","expert"],
["Il sécrète le castoréum, une substance à l'odeur de vanille utilisée autrefois en parfumerie et en alimentaire. Il est aujourd'hui pratiquement remplacé par des molécules de synthèse : le prélever suppose de tuer l'animal.","pointu"],
["Il peut rester 15 minutes sous l'eau, avec des paupières transparentes qui font office de lunettes de plongée et des lèvres qui se ferment derrière ses incisives pour ronger en apnée.","base"]],
v:[["Espèce ingénieure","Espèce qui modifie physiquement son habitat au point de créer des conditions de vie pour d'autres. Castor, corail, ver de terre, éléphant."]],
q:[["Qu'est-ce qui déclenche la construction d'un barrage chez le castor ?",["La vue de l'eau","Le bruit de l'eau qui coule","La température","La saison"],1,"Un haut-parleur diffusant du ruissellement suffit à le faire construire."],
["Pourquoi ses incisives sont-elles orange ?",["Une coloration alimentaire","Leur émail est renforcé au fer","Elles sont malades","C'est un signal social"],1,"Un alliage naturel plus dur que notre émail, qui s'auto-aiguise en biseau."]],
d:["symbiose","retour"]},

{id:"grand-dauphin",nom:"Grand dauphin",sci:"Tursiops truncatus",emo:"🐬",gr:"Mammifère",ord:"Cetacea",fam:"Delphinidés",bio:"ocean",
hab:"Eaux côtières tempérées et chaudes",rep:"Mondiale",taille:"2 à 4 m",poidsKg:300,vit:35,vie:45,
reg:"Carnivore",uicn:"LC",rar:2,
res:"Il a des noms propres. Chaque individu invente le sien enfant, et les autres l'utilisent pour l'appeler.",
f:[["Chaque dauphin développe vers un an un sifflement signature unique, qu'il garde toute sa vie. Les autres l'imitent pour s'adresser à lui — et un dauphin qui entend son propre sifflement reproduit par un haut-parleur répond, alors qu'il ignore celui d'un inconnu. C'est le plus proche équivalent connu d'un nom propre chez un animal.","expert"],
["À Shark Bay en Australie, certaines femelles portent une éponge de mer sur le rostre pour fouiller le fond sans se blesser. La technique se transmet de mère en fille depuis au moins 180 ans et ne s'est jamais répandue aux mâles.","pointu"],
["Il dort un hémisphère à la fois, un œil ouvert, pendant que l'autre moitié du cerveau continue de nager et de remonter respirer. Il ne dort jamais complètement.","base"],
["Sa respiration est volontaire, pas réflexe. Un dauphin anesthésié sans assistance cesse de respirer — ce qui rend toute chirurgie vétérinaire délicate.","pointu"],
["Il se reconnaît dans un miroir, capacité que très peu d'espèces possèdent. Des tests de 2018 suggèrent qu'il y parvient plus jeune que l'enfant humain.","pointu"]],
v:[["Sifflement signature","Vocalisation individuelle propre à un dauphin, apprise et non héritée. Elle sert d'identité : les congénères l'utilisent pour désigner son porteur en son absence."]],
q:[["Qu'est-ce qu'un sifflement signature ?",["Un cri d'alarme","Un nom propre inventé par l'individu et utilisé par les autres","Un chant de séduction","Un son d'écholocation"],1,"Un dauphin répond à son propre sifflement diffusé, pas à celui d'un inconnu."],
["Pourquoi une anesthésie est-elle risquée chez le dauphin ?",["Son cœur est fragile","Sa respiration est volontaire, pas réflexe","Il est allergique","Sa peau absorbe les produits"],1,"Endormi sans assistance, il cesse simplement de respirer."]],
d:["outils","records","sens"]},

{id:"beluga",nom:"Béluga",sci:"Delphinapterus leucas",emo:"🐳",gr:"Mammifère",ord:"Cetacea",fam:"Monodontidés",bio:"polaire",
hab:"Eaux arctiques et estuaires",rep:"Arctique et subarctique",taille:"3,5 à 5,5 m",poidsKg:1500,vit:22,vie:50,
reg:"Carnivore",uicn:"LC",rar:3,
res:"Le « canari des mers ». Le seul cétacé capable de tourner la tête — et de déformer son front à volonté.",
f:[["Ses vertèbres cervicales ne sont pas soudées, contrairement à celles de tous les autres cétacés. Il peut donc tourner la tête de côté, ce qui l'aide à manœuvrer dans les eaux peu profondes et encombrées de glace.","base"],
["Son melon — la bosse graisseuse de son front — est déformable à volonté. Il en change la forme pour focaliser ses sons d'écholocation, comme on règle une lentille. On peut le voir gonfler, s'aplatir et se creuser en surface.","pointu"],
["Son répertoire vocal est si riche et si aigu que les marins du XIXᵉ siècle l'entendaient à travers la coque de leurs bateaux et le surnommaient le canari des mers.","base"],
["Il mue chaque été en se frottant contre des graviers dans les estuaires — un comportement de spa collectif rare chez les cétacés.","pointu"],
["Un béluga capturé par la marine américaine, NOC, a spontanément modifié sa mécanique vocale pour imiter le rythme et la fréquence de la voix humaine. Un plongeur est remonté croyant avoir entendu un ordre. L'enregistrement, publié en 2012, reste troublant.","expert"]],
v:[["Melon","Organe graisseux du front des cétacés à dents, qui focalise les sons d'écholocation. Chez le béluga, il est mou et modifiable en temps réel."]],
q:[["Qu'est-ce qui distingue le béluga des autres cétacés ?",["Il n'a pas de dents","Ses vertèbres du cou ne sont pas soudées : il tourne la tête","Il vit en eau douce","Il n'écholocalise pas"],1,"Une mobilité utile dans les eaux encombrées de glace."],
["À quoi sert le melon du béluga ?",["À stocker de la graisse","À focaliser ses sons d'écholocation","À flotter","À se réchauffer"],1,"Il le déforme à volonté, comme on règle une lentille."]],
d:["sens","extremes"]},

{id:"morse",nom:"Morse",sci:"Odobenus rosmarus",emo:"🦭",gr:"Mammifère",ord:"Carnivora",fam:"Odobénidés",bio:"polaire",
hab:"Banquise et côtes arctiques",rep:"Arctique circumpolaire",taille:"2,7 à 3,6 m",poidsKg:1200,vit:35,vie:40,
reg:"Carnivore",uicn:"VU",rar:4,
res:"Il trouve ses coquillages à l'aveugle, dans la boue du fond, avec une moustache plus sensible que des doigts.",
f:[["Ses 400 à 700 vibrisses sont parmi les organes tactiles les plus sensibles connus : un morse distingue au toucher des plaques de 3 mm d'épaisseur. Dans la vase noire du fond, c'est son seul instrument.","pointu"],
["Il ne creuse pas avec ses défenses. Il balaie le sédiment d'un jet d'eau puissant expulsé par la bouche, et aspire la chair des coquillages en faisant le vide — jusqu'à 6 000 palourdes par plongée.","expert"],
["Ses défenses, deux canines pouvant atteindre un mètre, servent à hisser son corps hors de l'eau — d'où le nom du genre, Odobenus, « celui qui marche sur ses dents » — et à établir la hiérarchie.","base"],
["Le mâle possède des poches pharyngiennes gonflables qui lui servent à la fois de bouée pour dormir à la verticale dans l'eau, et de caisse de résonance pour produire des sons de cloche pendant la parade.","expert"],
["Avec la fonte de la banquise, des dizaines de milliers de morses s'échouent sur des plages. Paniqués, certains grimpent des falaises et en tombent : ces mortalités massives sont une conséquence directe de la disparition de la glace de mer.","base"]],
v:[["Vibrisse","Poil épais, raide et richement innervé — une moustache sensorielle. Chez le morse, le phoque et le chat, elle détecte des déformations minuscules du milieu."]],
q:[["Comment le morse déterre-t-il ses coquillages ?",["Avec ses défenses","Par un jet d'eau et une aspiration puissante","Avec ses nageoires","Il les ramasse en surface"],1,"Jusqu'à 6 000 palourdes par plongée, aspirées par le vide."],
["À quoi servent d'abord ses défenses ?",["À creuser","À se hisser hors de l'eau et à établir la hiérarchie","À chasser les phoques","À briser la glace"],1,"Odobenus signifie « celui qui marche sur ses dents »."]],
d:["sens","extremes"]},

{id:"phoque-weddell",nom:"Phoque de Weddell",sci:"Leptonychotes weddellii",emo:"🦭",gr:"Mammifère",ord:"Carnivora",fam:"Phocidés",bio:"polaire",
hab:"Sous la banquise côtière",rep:"Antarctique",taille:"2,5 à 3,5 m",poidsKg:450,vit:null,vie:30,
reg:"Piscivore",uicn:"LC",rar:4,
res:"Le mammifère qui vit le plus au sud de la planète. Il passe l'hiver antarctique sous la glace, en usant ses dents pour ne pas mourir noyé.",
f:[["Il plonge à 600 m et reste jusqu'à 80 minutes en apnée sous une couche de glace continue.","base"],
["Sa survie dépend entièrement de trous de respiration qu'il maintient ouverts en rongeant la glace avec ses incisives et ses canines. Ses dents s'usent jusqu'à la racine, et c'est ce qui le tue : un phoque de Weddell meurt rarement de vieillesse, il meurt quand il ne peut plus creuser.","expert"],
["Sa rate fonctionne comme un réservoir de globules rouges : elle en libère massivement au début de la plongée, ce qui augmente d'un coup la capacité de transport d'oxygène de son sang.","expert"],
["Il produit sous l'eau des vocalisations descendantes et sifflantes, entendues à des kilomètres, dont certaines sont ultrasoniques — découvertes seulement en 2017 alors qu'on l'étudie depuis un siècle.","pointu"]],
v:[["Apnée","Suspension de la respiration. Chez les mammifères plongeurs, elle s'accompagne d'un ralentissement du cœur, d'une redistribution du sang vers les organes vitaux et d'une tolérance élevée au CO₂."]],
q:[["Qu'est-ce qui limite la vie d'un phoque de Weddell ?",["Les orques","L'usure de ses dents, qui servent à ouvrir les trous de respiration","Le froid","La faim en été"],1,"Quand il ne peut plus creuser la glace, il ne peut plus respirer."],
["Quel est le rôle de sa rate en plongée ?",["Filtrer les toxines","Libérer une réserve de globules rouges","Réguler la température","Stocker de l'air"],1,"Un dopage sanguin naturel au moment de plonger."]],
d:["extremes","records"]},

{id:"grand-rhinolophe",nom:"Grand rhinolophe",sci:"Rhinolophus ferrumequinum",emo:"🦇",gr:"Mammifère",ord:"Chiroptera",fam:"Rhinolophidés",bio:"foret",
hab:"Grottes, greniers, bocage",rep:"Europe, Asie, Afrique du Nord",taille:"6 cm, 35 cm d'envergure",poidsKg:0.025,vit:25,vie:30,
reg:"Insectivore",uicn:"LC",rar:3,
res:"Il corrige l'effet Doppler de son propre vol, en temps réel, pour garder son sonar accordé. Un pilote d'avion n'en fait pas autant.",
f:[["Sa feuille nasale en fer à cheval — d'où son nom — n'est pas un ornement : elle focalise le faisceau ultrasonore qu'il émet par le nez, et non par la bouche comme la plupart des chauves-souris.","base"],
["Quand il vole vers un obstacle, l'écho lui revient à une fréquence plus haute que celle qu'il a émise : c'est l'effet Doppler, comme la sirène d'une ambulance qui approche. Il compense en abaissant sa propre fréquence d'émission, exactement de ce qu'il faut, pour que l'écho revienne toujours dans la même bande étroite.","expert"],
["Cette bande privilégiée correspond à une zone hypertrophiée de sa cochlée, la « fovéa acoustique », où sa résolution est extrême. Il maintient donc l'écho pile dans son point de netteté auditif — l'équivalent d'un autofocus permanent.","expert"],
["Ce réglage lui permet de détecter le battement d'ailes d'un papillon dans le feuillage, un signal que le fouillis d'échos rendrait illisible autrement.","pointu"],
["Il hiberne jusqu'à cinq mois, cœur ralenti à quelques battements par minute. Un dérangement hivernal peut lui coûter des semaines de réserves.","base"]],
v:[["Effet Doppler","Décalage de la fréquence d'une onde quand la source et le récepteur se déplacent l'un vers l'autre. C'est ce qui change le son d'une sirène qui passe."]],
q:[["Que compense le grand rhinolophe en vol ?",["Le vent","L'effet Doppler de son propre déplacement","La température","L'écho des autres chauves-souris"],1,"Il baisse sa fréquence d'émission pour que l'écho revienne toujours au même endroit."],
["Qu'est-ce que la fovéa acoustique ?",["Un os de l'oreille","Une zone de la cochlée à résolution extrême dans une bande étroite","Un muscle du tympan","Une cavité nasale"],1,"Il maintient l'écho pile dans son point de netteté auditif."]],
d:["sens","records"]},

{id:"panda-geant",nom:"Panda géant",sci:"Ailuropoda melanoleuca",emo:"🐼",gr:"Mammifère",ord:"Carnivora",fam:"Ursidés",bio:"montagne",
hab:"Forêts de bambou d'altitude",rep:"Centre de la Chine",taille:"1,2 à 1,8 m",poidsKg:110,vit:32,vie:25,
reg:"Herbivore",uicn:"VU",rar:4,
res:"Un carnivore avec un intestin de carnivore, qui a choisi de manger du bambou. Tout son quotidien découle de cette décision absurde.",
f:[["Il possède un « faux pouce » : un os du poignet, le sésamoïde radial, allongé en appendice opposable qui lui permet de tenir une tige de bambou. Ce n'est pas un doigt, c'est un os de poignet reconverti.","pointu"],
["Son tube digestif est court et simple, celui d'un carnivore. Il n'a ni panse de ruminant ni long cæcum. Résultat : il n'assimile qu'environ 17 % de ce qu'il avale, doit manger 12 à 38 kg de bambou par jour et passe jusqu'à 14 heures à mâcher.","expert"],
["Son génome contient toujours les gènes de la digestion carnée, mais le gène du récepteur au goût umami — celui de la viande — est inactivé. Il a perdu le goût de la viande avant d'avoir gagné les outils pour digérer les plantes.","expert"],
["Il se roule dans le crottin de cheval. Une étude de 2020 a montré que deux molécules du crottin frais bloquent la sensation de froid chez la souris : il s'enduirait d'un anesthésique thermique naturel.","expert"],
["Il est passé de « en danger » à « vulnérable » en 2016 après quarante ans de protection des forêts de bambou. Un des rares grands mammifères à avoir reculé d'un cran sur la liste rouge.","base"]],
v:[["Sésamoïde","Petit os logé dans un tendon, comme notre rotule. Chez le panda, l'un d'eux s'est allongé jusqu'à fonctionner comme un pouce — une bricole évolutive, pas une invention."]],
q:[["Qu'est-ce que le « pouce » du panda ?",["Un sixième doigt","Un os du poignet allongé","Une griffe modifiée","Un cartilage"],1,"Le sésamoïde radial reconverti — une bricole, pas un vrai doigt."],
["Pourquoi le panda mange-t-il jusqu'à 38 kg de bambou par jour ?",["Il est très gros","Son intestin de carnivore n'assimile que 17 % de ce qu'il avale","Le bambou est toxique","Il stocke pour l'hiver"],1,"Il a un régime d'herbivore avec la plomberie d'un carnivore."]],
d:["retour","taxo"]},

{id:"capybara",nom:"Capybara",sci:"Hydrochoerus hydrochaeris",emo:"🐹",gr:"Mammifère",ord:"Rodentia",fam:"Cavidés",bio:"riviere",
hab:"Berges, marais, prairies inondées",rep:"Amérique du Sud",taille:"1 à 1,3 m",poidsKg:55,vit:35,vie:10,
reg:"Herbivore",uicn:"LC",rar:2,
res:"Le plus grand rongeur du monde, et probablement l'animal le plus socialement tolérant de la planète.",
f:[["Il pèse jusqu'à 65 kg — un rongeur de la taille d'un gros chien. Son plus proche parent est le cochon d'Inde.","base"],
["Ses yeux, ses narines et ses oreilles sont alignés au sommet du crâne : il peut respirer, voir et entendre en gardant tout le corps immergé, comme un hippopotame.","pointu"],
["Il pratique la caecotrophie : il réingère certaines de ses crottes, molles et produites au petit matin, pour récupérer les nutriments libérés par la fermentation intestinale. Un herbivore qui digère deux fois.","pointu"],
["Sa tolérance sociale est telle qu'on l'observe couvert d'oiseaux, de singes, de tortues et même de caïmans juvéniles. Cette réputation n'est pas qu'une blague d'internet : elle a une base comportementale réelle, liée à une vie de groupe très dense et peu conflictuelle.","expert"],
["Il est la proie principale du jaguar, du caïman et de l'anaconda. Sa stratégie est simple : vivre en groupe, rester près de l'eau, et plonger.","base"]],
v:[["Caecotrophie","Réingestion de crottes molles issues du cæcum, riches en vitamines et protéines produites par les bactéries. Lapins, capybaras et de nombreux rongeurs en dépendent."]],
q:[["Quel est le plus proche parent du capybara ?",["Le castor","Le cochon d'Inde","Le rat","Le porc"],1,"C'est un cavidé — un cochon d'Inde de 60 kg."],
["Qu'est-ce que la caecotrophie ?",["Manger de la terre","Réingérer des crottes molles pour digérer deux fois","Ruminer","Stocker de la nourriture"],1,"Les bactéries du cæcum produisent des nutriments récupérés au second passage."]],
d:["symbiose","records"]},

{id:"oryctérope",nom:"Oryctérope du Cap",sci:"Orycteropus afer",emo:"🐷",gr:"Mammifère",ord:"Tubulidentata",fam:"Oryctéropodidés",bio:"savane",
hab:"Savanes et broussailles",rep:"Afrique subsaharienne",taille:"1 à 1,6 m",poidsKg:60,vit:40,vie:23,
reg:"Insectivore",uicn:"LC",rar:4,
res:"Le seul survivant d'un ordre entier de mammifères. Ses dents n'ont pas d'émail : elles sont faites de tubes.",
f:[["Il est le seul membre vivant de l'ordre des tubulidentés. Pas de famille cousine, pas de genre voisin : une branche à un seul rameau.","pointu"],
["Ses dents n'ont ni émail ni racine. Chacune est un faisceau de milliers de tubes de dentine soudés, à croissance continue — d'où le nom de l'ordre. Aucun autre mammifère n'a cette structure.","expert"],
["Il creuse si vite qu'il disparaît sous terre en cinq minutes dans un sol dur. Ses terriers abandonnés abritent ensuite phacochères, hyènes, mangoustes, chauves-souris, serpents et oiseaux : c'est un fournisseur de logement pour toute la savane.","pointu"],
["Il mange un seul fruit dans sa vie d'insectivore : le « concombre d'oryctérope », une plante dont les fruits mûrissent sous terre et qui dépend entièrement de lui pour disperser ses graines. Aucun autre animal ne les trouve.","expert"],
["Malgré une ressemblance frappante avec le tamanoir et le pangolin, il n'est apparenté ni à l'un ni à l'autre. Ses cousins les plus proches sont les éléphants et les damans.","pointu"]],
v:[["Ordre monotypique","Ordre ne contenant qu'une seule espèce vivante. Il signale une lignée ancienne dont toutes les autres branches ont disparu — comme l'oryctérope ou le tuatara."]],
q:[["Qu'ont de particulier les dents de l'oryctérope ?",["Elles repoussent","Elles sont faites de milliers de tubes de dentine, sans émail","Elles sont creuses","Il n'en a pas"],1,"D'où le nom de son ordre : les tubulidentés."],
["Quels sont ses plus proches parents ?",["Les tamanoirs","Les pangolins","Les éléphants et les damans","Les cochons"],2,"Sa ressemblance avec les autres mangeurs de fourmis est une convergence."]],
d:["taxo","convergence","symbiose"]},

{id:"wombat",nom:"Wombat commun",sci:"Vombatus ursinus",emo:"🐨",gr:"Mammifère",ord:"Diprotodontia",fam:"Vombatidés",bio:"foret",
hab:"Forêts et prairies, terriers",rep:"Sud-est de l'Australie, Tasmanie",taille:"70 à 120 cm",poidsKg:26,vit:40,vie:15,
reg:"Herbivore",uicn:"LC",rar:3,
res:"Le seul animal au monde à produire des crottes cubiques. Et il s'en sert.",
f:[["Ses excréments sont des cubes, à raison de 80 à 100 par nuit. Il les empile sur des rochers et des souches pour marquer son territoire — un cube ne roule pas, c'est tout l'intérêt.","base"],
["Le cube ne se forme pas dans l'anus mais dans les derniers mètres de l'intestin, dont la paroi présente deux zones très élastiques et deux zones rigides. Les contractions moulent la matière contre ces raideurs inégales. La découverte a valu le prix Ig Nobel de physique 2019, et intéresse la fabrication industrielle d'objets sans moule.","expert"],
["Sa poche s'ouvre vers l'arrière, à l'inverse de celle du kangourou : il creuse en permanence, une poche ouverte vers l'avant remplirait le petit de terre.","pointu"],
["Son arrière-train est blindé de cartilage épais. Poursuivi dans son terrier, il se laisse mordre les fesses sans dommage, ou bloque l'entrée avec, et peut écraser le crâne d'un prédateur contre le plafond de la galerie.","expert"],
["Ses terriers, longs de 30 m, ont servi de refuge à d'autres espèces pendant les grands feux australiens. Des caméras y ont filmé wallabies, échidnés et lézards à l'abri.","pointu"]],
v:[["Marquage territorial","Dépôt de signaux chimiques — urine, excréments, sécrétions — pour signaler une occupation. La forme cubique du wombat est une optimisation du support : le message reste où il a été posé."]],
q:[["Où se forment les crottes cubiques du wombat ?",["Dans l'anus","Dans les derniers mètres de l'intestin, à parois inégalement élastiques","Dans l'estomac","Elles sèchent en cubes après"],1,"Prix Ig Nobel de physique 2019 — et un intérêt industriel réel."],
["Pourquoi la poche du wombat s'ouvre-t-elle vers l'arrière ?",["Pour protéger du froid","Parce qu'il creuse en permanence","Pour porter plus de petits","Pour nager"],1,"Une poche vers l'avant se remplirait de terre à chaque coup de patte."]],
d:["records"]},

{id:"lamantin",nom:"Lamantin des Caraïbes",sci:"Trichechus manatus",emo:"🐋",gr:"Mammifère",ord:"Sirenia",fam:"Trichéchidés",bio:"riviere",
hab:"Estuaires, lagunes, rivières côtières",rep:"Golfe du Mexique, Caraïbes",taille:"2,7 à 3,5 m",poidsKg:500,vit:25,vie:60,
reg:"Herbivore",uicn:"VU",rar:4,
res:"Un herbivore marin de 500 kg sans aucun prédateur naturel — et dont la principale cause de mort est l'hélice d'un bateau.",
f:[["Ses plus proches parents ne sont pas les phoques mais les éléphants. Les siréniens et les proboscidiens partagent un ancêtre commun terrestre ; le lamantin a des ongles au bout de ses nageoires, vestiges de doigts.","pointu"],
["Ses molaires avancent en tapis roulant : les dents usées tombent à l'avant, de nouvelles poussent en permanence à l'arrière. Il broie des plantes chargées de sable toute sa vie sans jamais manquer de dents — exactement la limite qui tue l'éléphant.","expert"],
["Il n'a que six vertèbres cervicales, l'une des rarissimes exceptions à la règle des sept chez les mammifères. Il ne peut pas tourner la tête : il pivote de tout le corps.","expert"],
["On croit souvent qu'il a inspiré les légendes de sirènes. Christophe Colomb a bien noté avoir vu des « sirènes » peu gracieuses, mais l'origine du mythe est bien antérieure et méditerranéenne. La belle histoire est plus fragile qu'elle n'en a l'air.","expert"],
["Presque tous les lamantins adultes de Floride portent des cicatrices d'hélice, au point que les biologistes les identifient individuellement grâce à elles.","base"]],
v:[["Siréniens","Ordre des mammifères marins herbivores : lamantins et dugongs. Seul groupe de mammifères marins exclusivement végétariens, et parents des éléphants."]],
q:[["Quels sont les plus proches parents du lamantin ?",["Les phoques","Les éléphants","Les cétacés","Les hippopotames"],1,"Siréniens et proboscidiens partagent un ancêtre terrestre commun."],
["Comment le lamantin évite-t-il le sort de l'éléphant, tué par l'usure de ses dents ?",["Il mange mou","Ses molaires avancent en tapis roulant et se renouvellent sans fin","Il avale sans mâcher","Il ne vieillit pas"],1,"De nouvelles dents poussent en permanence à l'arrière de la mâchoire."]],
d:["taxo","convergence"]},

/* ============ OISEAUX ============ */

{id:"pic-noir",nom:"Pic noir",sci:"Dryocopus martius",emo:"🪶",gr:"Oiseau",ord:"Piciformes",fam:"Picidés",bio:"foret",
hab:"Vieilles futaies",rep:"Europe et Asie tempérée",taille:"45 à 50 cm",poidsKg:0.3,vit:null,vie:14,
reg:"Insectivore",uicn:"LC",rar:3,
res:"Il frappe un tronc vingt fois par seconde avec des décélérations qui assommeraient un boxeur. Et la raison pour laquelle il ne s'assomme pas n'est pas celle qu'on croit.",
f:[["Sa langue fait le tour de son crâne. Elle s'ancre à la base du bec, passe sous la mâchoire, contourne l'arrière de la tête et revient par-dessus le front — jusqu'à trois fois la longueur du bec, terminée par des barbules et une colle.","pointu"],
["On a longtemps enseigné que son crâne était un amortisseur, ce qui a inspiré des projets de casques. Une étude de 2022 filmant des pics à 4 000 images par seconde a montré l'inverse : la tête et le bec décélèrent ensemble, comme un marteau rigide. Amortir gaspillerait l'énergie du coup.","expert"],
["S'il ne se blesse pas, c'est parce que son cerveau est minuscule : l'énergie encaissée par un cerveau croît avec sa masse. Un cerveau de 2 grammes reste très en dessous du seuil de commotion, même à 400 g d'accélération. Il n'est pas protégé, il est trop petit pour être blessé.","expert"],
["Ses loges de nidification, creusées dans les vieux arbres, sont ensuite réutilisées par la chouette de Tengmalm, la sittelle, la martre, les chauves-souris et les abeilles sauvages. Là où le pic noir disparaît, une dizaine d'espèces perdent leur logement.","pointu"],
["Deux doigts vers l'avant, deux vers l'arrière, plus des plumes de queue rigides en trépied : il est verrouillé sur le tronc comme un élagueur sur ses crampons.","base"]],
v:[["Espèce parapluie","Espèce dont la protection entraîne mécaniquement celle de beaucoup d'autres, parce qu'elle exige un habitat vaste ou crée des ressources partagées."]],
q:[["Pourquoi le pic ne se blesse-t-il pas en frappant ?",["Son crâne amortit les chocs","Son cerveau est trop petit pour être commotionné","Il frappe moins fort qu'il n'y paraît","Il a un liquide protecteur"],1,"L'étude de 2022 a montré que la tête agit comme un marteau rigide, pas comme un amortisseur."],
["Où passe la langue du pic noir ?",["Dans son cou","Elle fait le tour du crâne","Dans son estomac","Elle est rétractée dans le bec"],1,"Ancrée à la base du bec, elle contourne l'arrière de la tête et revient par le front."]],
d:["records","symbiose"]},

{id:"autruche",nom:"Autruche d'Afrique",sci:"Struthio camelus",emo:"🪶",gr:"Oiseau",ord:"Struthioniformes",fam:"Struthionidés",bio:"savane",
hab:"Savanes et semi-déserts",rep:"Afrique",taille:"2,1 à 2,8 m",poidsKg:120,vit:70,vie:40,
reg:"Omnivore",uicn:"LC",rar:2,
res:"Le plus grand oiseau vivant, le plus rapide bipède du monde — et non, elle ne met jamais sa tête dans le sable.",
f:[["Elle court à 70 km/h en pointe et tient 50 km/h sur plusieurs kilomètres. Aucun animal à deux pattes ne fait mieux. Ses tendons stockent et restituent l'énergie comme des ressorts, à un rendement supérieur à celui du meilleur coureur humain.","base"],
["Elle est le seul oiseau à n'avoir que deux doigts par pied. Le doigt principal, énorme et muni d'un ongle en sabot, porte presque tout le poids — une réduction comparable à celle du cheval.","pointu"],
["Le mythe de la tête dans le sable vient de son comportement de dissimulation : couchée à plat, cou allongé au sol, elle disparaît dans les herbes vue de loin. Elle creuse aussi le sable pour retourner ses œufs. De loin, on croit voir une tête enfouie.","pointu"],
["Son œil mesure 5 cm, le plus grand de tous les vertébrés terrestres — plus gros que son propre cerveau.","base"],
["Le nid est communautaire : la femelle dominante y accepte les œufs des autres, et les dispose de façon à placer les siens au centre. En cas de prédation, ce sont les œufs de la périphérie, ceux des autres, qui sont perdus. Un bouclier fait des œufs des voisines.","expert"]],
v:[["Ratite","Oiseau coureur au sternum plat, sans bréchet, donc incapable de voler : autruche, émeu, nandou, casoar, kiwi. Ce groupe n'a pas perdu le vol une seule fois mais plusieurs, indépendamment."]],
q:[["L'autruche met-elle sa tête dans le sable ?",["Oui, pour se cacher","Non : elle se couche à plat, cou au sol, ce qui en donne l'illusion de loin","Oui, pour respirer","Seulement les jeunes"],1,"Elle creuse aussi le sable pour retourner ses œufs, ce qui a nourri le mythe."],
["Combien de doigts a l'autruche par pied ?",["4","3","2","1"],2,"Unique chez les oiseaux — une réduction comparable à celle du cheval."]],
d:["records","camouflage"]},

{id:"kiwi",nom:"Kiwi austral",sci:"Apteryx australis",emo:"🥝",gr:"Oiseau",ord:"Apterygiformes",fam:"Aptérygidés",bio:"foret",
hab:"Forêts et broussailles",rep:"Nouvelle-Zélande",taille:"45 à 55 cm",poidsKg:2.5,vit:null,vie:50,
reg:"Insectivore",uicn:"VU",rar:4,
res:"Un oiseau qui a renoncé au vol, à la vue et aux ailes, pour devenir un mammifère fouisseur. Et qui pond un œuf démesuré.",
f:[["Son œuf représente jusqu'à 20 % du poids de la femelle. Rapporté à sa taille, c'est l'un des plus gros œufs du monde animal : l'équivalent d'un nouveau-né humain de 15 kg. À la fin, la femelle ne peut plus manger, l'œuf comprime son estomac.","base"],
["Il est le seul oiseau dont les narines sont à l'extrémité du bec. Il chasse à l'odorat, en sondant l'humus, en reniflant — et il éternue régulièrement pour déboucher ses narines.","pointu"],
["Sa température corporelle est de 38 °C, deux degrés sous celle des autres oiseaux et proche de celle d'un mammifère. Il a des plumes en poils, des os pleins, un odorat développé et une vue déplorable : il occupe la niche écologique qu'un mammifère fouisseur aurait occupée si la Nouvelle-Zélande en avait eu.","expert"],
["Le séquençage de son ADN a révélé un parent inattendu : son plus proche cousin n'est pas le moa néo-zélandais mais l'oiseau-éléphant de Madagascar, éteint. Deux géants séparés par un océan, et un petit survivant entre les deux — ce qui a fait s'effondrer l'hypothèse d'une simple dérive des continents.","expert"]],
v:[["Radiation adaptative","Diversification rapide d'une lignée qui colonise des niches laissées vacantes. En Nouvelle-Zélande, sans mammifères terrestres, ce sont des oiseaux qui ont pris tous les rôles."]],
q:[["Où sont les narines du kiwi ?",["À la base du bec","À l'extrémité du bec","Sur le front","Il n'en a pas"],1,"Unique chez les oiseaux — il chasse à l'odorat en sondant l'humus."],
["Quel est le plus proche parent du kiwi ?",["Le moa","L'oiseau-éléphant de Madagascar","L'autruche","L'émeu"],1,"Une découverte génétique qui a défait l'explication par la dérive des continents."]],
d:["taxo","sens","convergence"]},

{id:"macareux",nom:"Macareux moine",sci:"Fratercula arctica",emo:"🐧",gr:"Oiseau",ord:"Charadriiformes",fam:"Alcidés",bio:"ocean",
hab:"Falaises côtières, haute mer l'hiver",rep:"Atlantique nord",taille:"28 à 30 cm",poidsKg:0.4,vit:88,vie:20,
reg:"Piscivore",uicn:"VU",rar:3,
res:"Il « vole » sous l'eau à coups d'ailes, et son bec change de couleur selon la saison — avec une surprise sous ultraviolet.",
f:[["Il rame avec ses ailes sous l'eau, comme un manchot, et se dirige avec les pattes. Un vol subaquatique jusqu'à 60 m de profondeur. En l'air, il doit battre des ailes 400 fois par minute pour se maintenir : le même organe fait deux métiers, mal.","base"],
["Il rapporte une dizaine de poissons à la fois, alignés en travers du bec. Sa langue plaque les prises contre des épines du palais orientées vers l'arrière : il peut en attraper d'autres sans lâcher les premières. Le record documenté dépasse 60 lançons.","pointu"],
["Son bec coloré est saisonnier : les plaques cornées vives tombent après la reproduction, laissant un bec terne et plus petit tout l'hiver. Les photos d'été et d'hiver semblent montrer deux espèces.","pointu"],
["En 2018, un ornithologue a braqué une lampe UV sur un macareux mort : les crêtes de son bec sont fluorescentes. Comme les macareux voient l'ultraviolet et pas nous, ils s'affichent depuis toujours dans une couleur que personne n'avait remarquée.","expert"],
["Les colonies islandaises déclinent avec le réchauffement des eaux, qui déplace les lançons dont dépendent les poussins. Le parent peut être en bonne santé et le poussin mourir de faim : c'est le décalage entre deux calendriers, pas la disparition d'une proie.","expert"]],
v:[["Décalage phénologique","Désynchronisation entre le calendrier d'une espèce et celui de sa ressource, sous l'effet du climat. L'oiseau arrive à l'heure, la nourriture n'y est plus."]],
q:[["Comment le macareux se propulse-t-il sous l'eau ?",["Avec ses pattes","Avec ses ailes, comme un manchot","Avec sa queue","Il flotte et plonge la tête"],1,"Les pattes ne servent qu'à diriger."],
["Qu'a-t-on découvert en 2018 sur son bec ?",["Il est venimeux","Ses crêtes sont fluorescentes sous UV","Il change tous les mois","Il est creux"],1,"Les macareux voient l'ultraviolet — ils s'affichaient dans une couleur invisible pour nous."]],
d:["biolum","migrations"]},

{id:"fregate",nom:"Frégate superbe",sci:"Fregata magnificens",emo:"🕊️",gr:"Oiseau",ord:"Suliformes",fam:"Frégatidés",bio:"ciel",
hab:"Ciel océanique tropical",rep:"Atlantique et Pacifique tropicaux",taille:"1 m, 2,3 m d'envergure",poidsKg:1.5,vit:150,vie:30,
reg:"Carnivore",uicn:"LC",rar:4,
res:"Un oiseau marin qui ne sait pas nager, ne peut pas se poser sur l'eau, et reste pourtant des semaines au-dessus de l'océan.",
f:[["Son squelette pèse moins que ses plumes. Rapportée à sa masse, son envergure est la plus grande de tous les oiseaux : elle plane des heures sans battre une aile.","base"],
["Elle n'a pas de glande uropygienne fonctionnelle : ses plumes ne sont pas imperméables. Tombée à l'eau, elle se gorge et se noie. Un oiseau marin qui doit éviter la mer.","pointu"],
["Des capteurs posés en 2016 ont montré qu'elle grimpe dans les cumulus jusqu'à 4 000 m en profitant des ascendances, puis plane en descendant pendant des dizaines de kilomètres. Elle utilise la météo comme un escalier.","expert"],
["Les mêmes capteurs ont mesuré son sommeil en vol : moins de 45 minutes par jour, par micro-siestes de quelques secondes, parfois avec un seul hémisphère, parfois avec les deux. Au sol, elle dort plus de 12 heures. Elle vit donc des semaines en privation de sommeil sans dommage apparent — ce que nous ne savons pas expliquer.","expert"],
["Le mâle gonfle un sac gulaire rouge vif pendant des heures pour attirer les femelles qui survolent la colonie. Et elle vole souvent sa nourriture à d'autres oiseaux marins en vol, d'où son surnom de frégate-pirate.","base"]],
v:[["Cleptoparasitisme","Voler la nourriture déjà capturée par un autre animal. Fréquent chez les frégates, les labbes, les hyènes et certains rapaces — souvent en complément de la chasse, rarement à la place."]],
q:[["Que se passe-t-il si une frégate tombe à l'eau ?",["Elle nage","Elle se gorge d'eau et se noie","Elle décolle aussitôt","Elle plonge pour pêcher"],1,"Ses plumes ne sont pas imperméables : un oiseau marin qui doit éviter la mer."],
["Combien dort une frégate en vol au-dessus de l'océan ?",["8 heures","Moins de 45 minutes par jour","Elle ne dort pas du tout","4 heures"],1,"Par micro-siestes de quelques secondes, parfois un seul hémisphère à la fois."]],
d:["records","migrations"]},

{id:"fou-de-bassan",nom:"Fou de Bassan",sci:"Morus bassanus",emo:"🕊️",gr:"Oiseau",ord:"Suliformes",fam:"Sulidés",bio:"ocean",
hab:"Falaises et haute mer",rep:"Atlantique nord",taille:"90 cm, 1,8 m d'envergure",poidsKg:3,vit:100,vie:25,
reg:"Piscivore",uicn:"LC",rar:3,
res:"Il se jette à 100 km/h dans l'eau, tête la première, des dizaines de fois par jour. Chaque partie de son corps est conçue pour encaisser cet impact.",
f:[["Il pique d'une trentaine de mètres, ailes repliées en flèche au dernier instant, et entre dans l'eau à environ 100 km/h en atteignant 10 à 15 m de profondeur.","base"],
["Il n'a pas de narines externes : elles sont fermées et débouchent à l'intérieur du bec. À cette vitesse, des narines ouvertes injecteraient l'eau sous pression dans son crâne.","pointu"],
["Un réseau de sacs aériens sous la peau du cou et de la poitrine amortit le choc, comme des coussins gonflables. Il gonfle sa combinaison avant chaque plongeon.","pointu"],
["Une étude de 2016 a montré que la sécurité du plongeon dépend d'un angle et d'une vitesse précis : au-delà d'un certain seuil, la compression fait flamber le cou. Le fou reste en dessous — la limite est anatomique, et elle explique pourquoi aucun oiseau plus gros ne plonge de cette façon.","expert"],
["La colonie de Bass Rock, en Écosse, qui a donné son nom à l'espèce, comptait 150 000 individus avant la grippe aviaire H5N1 de 2022, qui a tué des dizaines de milliers d'oiseaux en une saison. Les survivants ont désormais l'iris noir au lieu de bleu — une marque d'infection guérie que les ornithologues utilisent pour suivre l'épidémie.","expert"]],
v:[["Sac aérien","Poche d'air prolongeant les poumons des oiseaux. Elle sert à la respiration continue, à l'allègement — et chez le fou, à l'amortissement des chocs."]],
q:[["Pourquoi le fou de Bassan n'a-t-il pas de narines externes ?",["Il ne sent rien","À 100 km/h, l'eau serait injectée sous pression dans son crâne","Pour économiser du poids","Pour plonger plus profond"],1,"Elles sont fermées et débouchent à l'intérieur du bec."],
["Comment reconnaît-on aujourd'hui un fou ayant survécu à la grippe aviaire ?",["Ses plumes blanchissent","Son iris devient noir au lieu de bleu","Il perd des plumes","Il ne plonge plus"],1,"Une marque qui sert à suivre l'épidémie dans les colonies."]],
d:["records","extremes"]},

{id:"hoazin",nom:"Hoazin huppé",sci:"Opisthocomus hoazin",emo:"🦃",gr:"Oiseau",ord:"Opisthocomiformes",fam:"Opisthocomidés",bio:"riviere",
hab:"Végétation des berges amazoniennes",rep:"Bassin de l'Amazone et de l'Orénoque",taille:"65 cm",poidsKg:0.8,vit:null,vie:12,
reg:"Herbivore",uicn:"LC",rar:5,
res:"Le seul oiseau qui digère les feuilles par fermentation, comme une vache. Ses poussins ont des griffes aux ailes.",
f:[["Son jabot est hypertrophié et cloisonné : les feuilles y fermentent grâce à des bactéries pendant 24 à 48 heures avant de passer dans l'estomac. C'est le seul oiseau connu à pratiquer une fermentation avant l'estomac, comme un ruminant.","pointu"],
["Cette fermentation dégage une odeur puissante de fumier, d'où son surnom d'« oiseau puant ». Elle le rend immangeable, ce qui l'a longtemps protégé de la chasse — un camouflage olfactif involontaire.","base"],
["Son jabot est si volumineux qu'il occupe la place des muscles du vol. Le hoazin vole mal, sur quelques dizaines de mètres, et s'appuie sur une callosité du bréchet pour se poser dans les branches. Digérer des feuilles lui a coûté le vol.","expert"],
["Ses poussins portent deux griffes fonctionnelles au pli de chaque aile. Menacés, ils se jettent à l'eau, nagent, puis remontent dans la végétation en s'agrippant avec ces griffes. Elles disparaissent à l'âge adulte. Ce n'est pas un vestige d'Archaeopteryx — c'est une réinvention récente, une convergence.","expert"],
["Sa position dans l'arbre des oiseaux reste débattue depuis un siècle. Les analyses génomiques le placent seul sur une branche isolée depuis environ 64 millions d'années : il est le dernier représentant de son ordre.","pointu"]],
v:[["Fermentation pré-gastrique","Digestion des végétaux par des bactéries avant l'estomac acide. Ruminants, kangourous, langurs — et un seul oiseau."]],
q:[["Qu'a de particulier la digestion du hoazin ?",["Il ne digère pas les fibres","Il fermente les feuilles dans son jabot, avant l'estomac","Il avale des pierres","Il digère en volant"],1,"Le seul oiseau à pratiquer une fermentation de type ruminant."],
["Que sont les griffes des poussins de hoazin ?",["Un vestige d'Archaeopteryx","Une réinvention récente, par convergence","Des plumes durcies","Une malformation"],1,"Elles disparaissent à l'âge adulte et n'ont rien d'un héritage direct."]],
d:["taxo","convergence","symbiose"]},

{id:"kakapo",nom:"Kakapo",sci:"Strigops habroptilus",emo:"🦜",gr:"Oiseau",ord:"Psittaciformes",fam:"Strigopidés",bio:"foret",
hab:"Forêts insulaires protégées",rep:"Nouvelle-Zélande (3 îles sanctuaires)",taille:"60 cm",poidsKg:2.5,vit:null,vie:60,
reg:"Herbivore",uicn:"CR",rar:5,
res:"Le seul perroquet incapable de voler, le plus lourd du monde, et probablement l'oiseau le plus surveillé de la planète : chaque individu a un nom.",
f:[["Il ne vole pas. Dans une Nouvelle-Zélande sans mammifères terrestres, son unique prédateur était un aigle géant chassant à vue : sa stratégie était de se figer et de compter sur son camouflage vert moussu. Face aux chats et aux hermines apportés par l'homme, qui chassent à l'odorat, cette immobilité est devenue une condamnation.","expert"],
["Le mâle creuse une cuvette dans le sol, orientée comme un réflecteur acoustique, et y émet un « boum » très grave des heures durant, jusqu'à 5 km à la ronde. Les fréquences basses portent loin mais ne se localisent pas : les femelles mettent parfois des nuits à le trouver.","pointu"],
["Il ne se reproduit que les années de fructification massive du rimu, un arbre qui fructifie tous les deux à quatre ans. Les équipes de conservation surveillent donc les arbres pour savoir s'il y aura des poussins.","pointu"],
["Il en restait 51 en 1995. Ils sont environ 250 aujourd'hui. Chacun porte un nom et un émetteur, son ADN est séquencé, et les accouplements sont planifiés pour préserver la diversité génétique. C'est une des populations sauvages les plus intensivement gérées au monde.","expert"],
["Il dégage une forte odeur douce de miel et de fleurs — parfaite pour retrouver ses congénères dans le noir, catastrophique face à des prédateurs à l'odorat.","base"]],
v:[["Lek","Terrain de parade où les mâles s'exhibent côte à côte et où les femelles viennent choisir. Le mâle ne fournit que ses gènes : ni territoire, ni nourriture, ni soins."]],
q:[["Pourquoi l'immobilité du kakapo est-elle devenue mortelle ?",["Il est trop lourd","Ses prédateurs introduits chassent à l'odorat, pas à vue","Il ne voit plus","Le sol a changé"],1,"Sa défense était conçue contre un aigle chassant à vue."],
["Qu'est-ce qui déclenche une saison de reproduction du kakapo ?",["La pluie","La fructification massive du rimu","La température","La lune"],1,"Les équipes surveillent les arbres pour prévoir les naissances."]],
d:["retour","camouflage"]},

{id:"paradisier",nom:"Paradisier superbe",sci:"Lophorina niedda",emo:"🪶",gr:"Oiseau",ord:"Passeriformes",fam:"Paradiséidés",bio:"jungle",
hab:"Forêts de montagne",rep:"Nouvelle-Guinée",taille:"26 cm",poidsKg:0.09,vit:null,vie:12,
reg:"Frugivore",uicn:"LC",rar:5,
res:"Ses plumes absorbent 99,95 % de la lumière visible. C'est le noir le plus profond du monde vivant, et il sert à tromper l'œil.",
f:[["Ses plumes noires de parade absorbent jusqu'à 99,95 % de la lumière — comparable aux matériaux les plus noirs fabriqués en laboratoire. Le noir d'une voiture repeinte absorbe environ 97 %.","base"],
["La cause n'est pas un pigment mais une structure : les barbules des plumes sont courbées et hérissées de micro-épines qui piègent la lumière en la faisant rebondir jusqu'à extinction. La lumière entre et ne ressort pas.","expert"],
["Ce noir absolu supprime tout relief et toute ombre : l'œil ne peut plus juger de la forme ni de la distance. Le disque de plumes devient un trou dans l'espace, sur lequel les taches bleu iridescent du mâle semblent flotter. C'est une illusion d'optique, pas un simple contraste.","expert"],
["Le mâle danse pendant des heures pour une seule femelle, en se déployant en ovale noir. Chaque espèce de paradisier a sa chorégraphie et sa forme propres.","base"],
["Cette extravagance a pu apparaître parce que la Nouvelle-Guinée offre des fruits abondants toute l'année et peu de prédateurs : les mâles ont du temps et de l'énergie à dépenser en spectacle. La sélection sexuelle a alors emballé le processus.","pointu"]],
v:[["Couleur structurelle","Couleur produite par la géométrie microscopique d'une surface plutôt que par un pigment. Ailes de morpho, plumes de paon, peau de caméléon — et le super-noir du paradisier."]],
q:[["D'où vient le noir extrême du paradisier ?",["D'un pigment très concentré","De micro-épines qui piègent la lumière dans les plumes","D'une couche de suie","De l'ombre du sous-bois"],1,"La lumière entre, rebondit et ne ressort plus."],
["À quoi sert ce noir dans la parade ?",["À se cacher","À supprimer le relief pour que les taches colorées semblent flotter","À se réchauffer","À effrayer les rivaux"],1,"Une illusion d'optique construite, pas un simple contraste."]],
d:["couleur","camouflage"]},

{id:"martin-pecheur",nom:"Martin-pêcheur d'Europe",sci:"Alcedo atthis",emo:"🐦",gr:"Oiseau",ord:"Coraciiformes",fam:"Alcédinidés",bio:"riviere",
hab:"Berges de rivières claires",rep:"Europe, Asie, Afrique du Nord",taille:"17 cm",poidsKg:0.04,vit:45,vie:7,
reg:"Piscivore",uicn:"LC",rar:2,
res:"Son bec a résolu un problème d'aérodynamique que les ingénieurs japonais n'arrivaient pas à régler — et cette histoire de biomimétisme, elle, est vraie.",
f:[["Il n'est pas bleu. Ses plumes ne contiennent aucun pigment bleu : des structures microscopiques dispersent la lumière et ne renvoient que le bleu. Une plume broyée devient brune — la couleur disparaît avec la structure.","pointu"],
["Le train à grande vitesse japonais Shinkansen provoquait un bang assourdissant à la sortie des tunnels, à cause de l'onde de pression accumulée devant lui. L'ingénieur Eiji Nakatsu, ornithologue amateur, a fait redessiner le nez du train d'après le bec du martin-pêcheur, qui entre dans l'eau sans éclaboussure. Le bang a disparu, et le train consomme 15 % d'énergie en moins. Contrairement à beaucoup d'histoires de biomimétisme, celle-ci est documentée par l'ingénieur lui-même.","expert"],
["Il vise en corrigeant la réfraction, comme le poisson-archer mais dans l'autre sens. Une membrane nictitante recouvre son œil au moment de l'impact : il termine sa plongée à l'aveugle, sur une trajectoire calculée avant d'entrer dans l'eau.","expert"],
["Il doit manger environ 60 % de son poids par jour et meurt vite en cas de gel prolongé, qui lui ferme l'accès à l'eau. Les hivers rigoureux effondrent les populations, qui remontent en deux ou trois ans grâce à des nichées nombreuses.","pointu"]],
v:[["Biomimétisme","Conception technique inspirée d'une solution du vivant. Le domaine est riche en récits embellis : la filiation n'est solide que si un ingénieur l'a documentée, comme ici."]],
q:[["Qu'a inspiré le bec du martin-pêcheur ?",["Un casque de moto","Le nez du train Shinkansen","Une combinaison de plongée","Une pale d'éolienne"],1,"Documenté par l'ingénieur Eiji Nakatsu lui-même : plus de bang, et 15 % d'énergie en moins."],
["Pourquoi une plume de martin-pêcheur broyée devient-elle brune ?",["Elle s'oxyde","Sa couleur est structurelle, pas pigmentaire","Elle sèche","Le bleu est fragile à la lumière"],1,"Détruire la structure détruit la couleur."]],
d:["couleur","sens"]},

{id:"coucou-gris",nom:"Coucou gris",sci:"Cuculus canorus",emo:"🐦",gr:"Oiseau",ord:"Cuculiformes",fam:"Cuculidés",bio:"foret",
hab:"Bocages, roselières, lisières",rep:"Europe et Asie, hiverne en Afrique",taille:"33 cm",poidsKg:0.12,vit:null,vie:12,
reg:"Insectivore",uicn:"LC",rar:2,
res:"Il ne construit jamais de nid. Toute son évolution est une course aux armements contre les oiseaux qu'il parasite.",
f:[["La femelle pond un œuf dans le nid d'une autre espèce, en 10 secondes, souvent après avoir retiré un œuf de l'hôte pour que le compte reste juste.","base"],
["Le poussin éclôt en premier et, encore aveugle et nu, hisse un à un les autres œufs sur son dos creux pour les basculer hors du nid. Il élimine toute concurrence dans ses premières heures de vie.","base"],
["Chaque femelle est spécialisée sur une espèce hôte et pond des œufs qui en imitent la couleur et les motifs. Ces lignées, appelées gentes, se transmettent par la mère seule — le patron de l'œuf est porté sur le chromosome W, l'équivalent femelle du Y. Les mâles, eux, se croisent entre gentes, ce qui maintient une seule espèce.","expert"],
["C'est une course sans fin : les hôtes apprennent à repérer les faux œufs, les coucous améliorent l'imitation. Certaines populations d'hôtes rejettent aujourd'hui plus de 90 % des œufs parasites, d'autres n'y voient rien — selon depuis combien de temps le coucou est présent chez elles.","expert"],
["Son chant à deux notes lui a donné son nom dans presque toutes les langues d'Europe, et a donné le mot « cocu ».","base"]],
v:[["Parasitisme de couvée","Faire élever sa descendance par une autre espèce. Il libère le parasite de tout coût parental et enclenche une coévolution antagoniste avec l'hôte."]],
q:[["Comment se transmet le motif de l'œuf chez le coucou ?",["Par le père","Par la mère seule, via le chromosome W","Par apprentissage","Au hasard"],1,"Les mâles se croisent entre lignées, ce qui maintient une espèce unique."],
["Que fait le poussin de coucou en éclosant ?",["Il crie plus fort","Il éjecte les autres œufs hors du nid","Il imite les autres poussins","Il attend d'être nourri"],1,"Aveugle et nu, il les hisse sur son dos creux."]],
d:["parasites","camouflage"]},

{id:"etourneau",nom:"Étourneau sansonnet",sci:"Sturnus vulgaris",emo:"🐦",gr:"Oiseau",ord:"Passeriformes",fam:"Sturnidés",bio:"ville",
hab:"Villes, cultures, roselières",rep:"Europe, introduit sur tous les continents",taille:"21 cm",poidsKg:0.08,vit:70,vie:15,
reg:"Omnivore",uicn:"LC",rar:2,
res:"Des dizaines de milliers d'oiseaux qui tournent comme un seul corps, sans chef ni signal. Chacun ne surveille que sept voisins.",
f:[["Les murmurations rassemblent jusqu'à un million d'individus, changeant de direction en une fraction de seconde sans jamais se heurter.","base"],
["Des reconstructions en 3D ont montré que chaque étourneau ajuste sa trajectoire sur ses sept voisins les plus proches — pas sur ceux qui sont à une certaine distance, mais sur un nombre fixe. Cette règle garde le groupe cohérent quelle que soit sa densité.","expert"],
["La corrélation entre oiseaux est dite sans échelle : quand un individu vire, l'information traverse tout le groupe quelle que soit sa taille, sans s'atténuer. Les physiciens décrivent ce comportement avec les mêmes équations que les transitions de phase de la matière — le nuage est constamment au bord du basculement.","expert"],
["Il imite tout : autres oiseaux, sonneries, alarmes de voiture. Mozart en a possédé un qui reproduisait un thème de son concerto en sol majeur, et lui a offert des funérailles.","pointu"],
["Une centaine d'individus lâchés à Central Park en 1890 par un homme qui voulait introduire aux États-Unis tous les oiseaux cités par Shakespeare a donné plus de 150 millions d'étourneaux nord-américains. L'anecdote shakespearienne est aujourd'hui contestée par les historiens, mais l'introduction et son résultat, eux, sont bien réels.","expert"]],
v:[["Corrélation sans échelle","Propriété d'un groupe où l'influence d'un individu se propage à l'ensemble quelle que soit sa taille. Elle rend le collectif extrêmement réactif."]],
q:[["Sur combien de voisins un étourneau règle-t-il sa trajectoire ?",["Tous ceux qu'il voit","Les sept plus proches","Un seul, devant lui","Le centre du groupe"],1,"Un nombre fixe, pas une distance — la cohésion tient quelle que soit la densité."],
["Comment les physiciens décrivent-ils une murmuration ?",["Comme un fluide","Comme un système au bord d'une transition de phase","Comme un cristal","Comme un gaz parfait"],1,"Le nuage est en permanence au seuil du basculement, donc hypersensible."]],
d:["eusocial","villes"]},

{id:"condor-andes",nom:"Condor des Andes",sci:"Vultur gryphus",emo:"🦅",gr:"Oiseau",ord:"Cathartiformes",fam:"Cathartidés",bio:"montagne",
hab:"Hautes montagnes et côtes",rep:"Cordillère des Andes",taille:"1,2 m, 3,2 m d'envergure",poidsKg:12,vit:90,vie:70,
reg:"Charognard",uicn:"VU",rar:5,
res:"Le plus lourd oiseau volant du monde. Il a parcouru 170 km sans battre une seule fois des ailes.",
f:[["Avec 3,2 m d'envergure pour 15 kg chez les gros mâles, c'est le plus lourd oiseau capable de vol battu. Décoller lui coûte tellement qu'il choisit des perchoirs en falaise d'où il peut se laisser tomber.","base"],
["Des capteurs posés en 2020 ont montré qu'il ne bat des ailes que pendant 1 % de son temps de vol, presque uniquement au décollage. Un individu a plané 5 heures et parcouru plus de 170 km sans un seul battement.","expert"],
["Il n'a pas d'organe vocal : sans syrinx, il ne peut que siffler et grogner. L'un des plus grands oiseaux du monde est quasiment muet.","pointu"],
["Contrairement aux vautours d'Afrique, les cathartidés américains ont un odorat développé et repèrent les charognes sous le couvert forestier. La ressemblance entre vautours de l'Ancien et du Nouveau Monde est une convergence : ils ne sont pas proches parents.","expert"],
["Il ne pond qu'un œuf tous les deux ans et n'est mature qu'à 8 ans. Sa lente reproduction rend chaque adulte empoisonné — souvent par des appâts destinés aux pumas — très difficile à remplacer.","pointu"]],
v:[["Vol plané","Vol sans battement, où la perte d'altitude est compensée par les ascendances : thermiques au-dessus des sols chauds, ascendances de pente le long des reliefs."]],
q:[["Quelle proportion de son temps de vol le condor passe-t-il à battre des ailes ?",["50 %","20 %","1 %","Il ne bat jamais"],2,"Presque uniquement au décollage — un vol de 170 km sans un battement a été mesuré."],
["Pourquoi le condor est-il presque muet ?",["Il est timide","Il n'a pas de syrinx","Il vit trop haut","Il communique par gestes"],1,"Sans organe vocal, il ne peut que siffler et grogner."]],
d:["records","convergence"]},

{id:"becasseau-maubeche",nom:"Bécasseau maubèche",sci:"Calidris canutus",emo:"🐦",gr:"Oiseau",ord:"Charadriiformes",fam:"Scolopacidés",bio:"polaire",
hab:"Toundra l'été, vasières l'hiver",rep:"De l'Arctique à la Terre de Feu",taille:"25 cm",poidsKg:0.135,vit:70,vie:20,
reg:"Carnivore",uicn:"NT",rar:4,
res:"Il fait 15 000 km deux fois par an. Pour y arriver, il digère ses propres organes en vol.",
f:[["Avant le grand départ, il double presque sa masse en graisse. Puis il réduit son estomac, son foie et ses intestins — devenus inutiles pendant un vol sans escale — et développe son cœur et ses muscles pectoraux. À l'arrivée, il reconstruit ses organes digestifs en quelques jours. Il remodèle son corps deux fois par an.","expert"],
["Sa migration dépend d'une seule escale critique : la baie du Delaware, où il se gorge d'œufs de limules pour reconstituer ses réserves. La surpêche des limules a fait chuter la sous-espèce rufa de plus de 75 %. Deux espèces sans aucun lien de parenté, liées par une semaine dans l'année.","expert"],
["Un individu bagué en 1995 et surnommé Moonbird a été revu pendant vingt ans. On estime qu'il a parcouru plus de distance qu'un aller-retour Terre-Lune.","pointu"],
["Les jeunes nés dans un Arctique qui se réchauffe éclosent après le pic d'insectes et grandissent plus petits, avec un bec plus court. Arrivés en Afrique, ce bec n'atteint plus les mollusques enfouis. La conséquence d'un printemps décalé se paie un continent plus loin, des mois plus tard.","expert"]],
v:[["Plasticité phénotypique","Capacité d'un organisme à modifier sa forme ou sa physiologie sans changer ses gènes. Chez le bécasseau, elle va jusqu'à la fonte réversible d'organes entiers."]],
q:[["Que fait le bécasseau maubèche de ses organes digestifs avant un vol sans escale ?",["Il les remplit","Il les réduit, puis les reconstruit à l'arrivée","Il ne change rien","Il les vide seulement"],1,"Il remodèle son corps deux fois par an."],
["De quelle espèce dépend son escale critique dans la baie du Delaware ?",["Le crabe bleu","La limule","La moule","Le hareng"],1,"Ses œufs sont la ressource qui permet de reconstituer les réserves."]],
d:["migrations","symbiose","records"]},

{id:"engoulevent-nuttall",nom:"Engoulevent de Nuttall",sci:"Phalaenoptilus nuttallii",emo:"🐦",gr:"Oiseau",ord:"Caprimulgiformes",fam:"Caprimulgidés",bio:"desert",
hab:"Zones arides et rocailleuses",rep:"Ouest de l'Amérique du Nord",taille:"19 à 21 cm",poidsKg:0.045,vit:null,vie:5,
reg:"Insectivore",uicn:"LC",rar:5,
res:"Le seul oiseau au monde qui hiberne vraiment. Les Hopis l'appelaient « le dormeur » bien avant que la science ne le découvre.",
f:[["En 1946, un chercheur a trouvé un engoulevent immobile dans une anfractuosité du désert de Californie, froid et sans réaction. Revenu les hivers suivants, il a retrouvé le même individu, bagué, au même endroit. C'était le premier oiseau hibernant jamais documenté.","base"],
["Sa température corporelle descend à 5 °C et sa consommation d'oxygène chute de plus de 90 %. Il peut rester ainsi des semaines, voire des mois. Aucun autre oiseau ne va aussi loin : les autres pratiquent au mieux une torpeur de quelques heures.","pointu"],
["Les Hopis l'appellent hölchoko, « le dormeur ». Le savoir était local et ancien ; il a fallu attendre le milieu du XXᵉ siècle pour qu'il entre dans la littérature scientifique. C'est un rappel utile sur ce que « découvrir » veut dire.","expert"],
["Son plumage imite si bien la roche et les lichens qu'on peut passer à côté sans le voir. Il niche à même le sol, sans nid.","base"],
["Sa bouche s'ouvre démesurément, bien au-delà de son bec minuscule : c'est un filet à insectes qu'il ouvre en volant dans le crépuscule.","pointu"]],
v:[["Hibernation","Torpeur profonde et prolongée, de plusieurs semaines à plusieurs mois, avec chute massive de la température et du métabolisme. À distinguer de la torpeur quotidienne du colibri."]],
q:[["Qu'est-ce qui rend l'engoulevent de Nuttall unique parmi les oiseaux ?",["Il vole la nuit","Il hiberne vraiment, des semaines durant","Il ne mange pas","Il pond en hiver"],1,"Les autres oiseaux pratiquent au mieux une torpeur de quelques heures."],
["Qui connaissait ce comportement bien avant la science occidentale ?",["Personne","Les Hopis, qui l'appelaient « le dormeur »","Les Romains","Les naturalistes du XVIIIᵉ"],1,"Un rappel utile sur ce que « découvrir » signifie."]],
d:["extremes","records"]}

]);
